//! Production room processor impulse stability, off the device callback.
use musicos_desktop::local::listening::Reverb;
fn main(){let mut results=Vec::new();for depth in [0.,0.5,1.]{let mut room=Reverb::default();room.set(1.);room.set_depth(depth);for _ in 0..48000{room.process([0.;2]);}let mut peak=0_f32;let mut late=0;let mut count=0;let mut tail=0.;let mut largest_step=0_f32;let mut previous=[0.;2];for frame in 0..384000{let input=if frame==0{[0.5;2]}else{[0.;2]};let output=room.process(input);for channel in 0..2{assert!(output[channel].is_finite());peak=peak.max(output[channel].abs());largest_step=largest_step.max((output[channel]-previous[channel]).abs());}previous=output;if frame>=4800&&frame<48000{count+=1;if output.iter().any(|s|s.abs()>0.00001){late+=1;}}if frame>=336000{tail+=output.iter().map(|s|s*s).sum::<f32>();}}let mut dc=Reverb::default();dc.set(1.);dc.set_depth(depth);for _ in 0..48000{dc.process([0.;2]);}let mut dc_peak=0_f32;for _ in 0..192000{let y=dc.process([0.75;2]);dc_peak=dc_peak.max(y[0].abs()).max(y[1].abs());}results.push(serde_json::json!({"sustained_input":0.75,"sustained_peak":dc_peak,"depth":depth,"peak":peak,"early_tail_occupancy":late as f32/count as f32,"late_tail_energy":tail,"maximum_step":largest_step}));}println!("{}",serde_json::to_string_pretty(&results).unwrap());}
